using SharpTS.Tests.Infrastructure;
using Xunit;
namespace SharpTS.Tests.SharedTests;
public sealed class InterpreterObjectSymbolPropertiesTests
{
    public static IEnumerable<object[]> Cases()
    {
        yield return ["original", "const O:any=Object,key=Symbol('k');O[key]=1;const d:any=Object.getOwnPropertyDescriptor(O,key);console.log(O[key],d===undefined,Object.getOwnPropertySymbols(O).includes(key),Object.hasOwn(O,key));\n", "1 false true true\n"];
        yield return ["identity", "const O:any=Object,a=Symbol('x'),b=Symbol('x');O[a]=1;O[b]=2;O[String(a)]=3;console.log(O[a],O[b],O[String(a)],Object.getOwnPropertySymbols(O).length);", "1 2 3 2\n"];
        yield return ["undefined-and-missing", "const O:any=Object,a=Symbol('a'),b=Symbol('b');O[a]=undefined;const d:any=Object.getOwnPropertyDescriptor(O,a),all:any=Object.getOwnPropertyDescriptors(O);console.log(Object.hasOwn(O,a),a in O,d.value===undefined,all[a].value===undefined,Object.hasOwn(O,b),b in O,typeof O[b]);", "true true true true false false undefined\n"];
        yield return ["readonly-descriptor", "const O:any=Object,k=Symbol('k');Object.defineProperty(O,k,{value:7,writable:false,enumerable:false,configurable:false});O[k]=9;const d:any=Reflect.getOwnPropertyDescriptor(O,k);console.log(O[k],Reflect.set(O,k,8),Reflect.deleteProperty(O,k),d.writable,d.enumerable,d.configurable);try{Object.defineProperty(O,k,{value:10});}catch(error){console.log(error instanceof TypeError);}", "7 false false false false false\ntrue\n"];
        yield return ["own-accessor-receiver", "const O:any=Object,k=Symbol('k');O.tag=7;Object.defineProperty(O,k,{get:function(this:any){return this.tag;},set:function(this:any,value:any){this.mark=value;},configurable:true});const receiver:any={tag:8};console.log(O[k],Reflect.get(O,k,receiver),Reflect.set(O,k,9,receiver),receiver.mark,typeof O.mark);O[k]=10;const d:any=Object.getOwnPropertyDescriptor(O,k);console.log(O.mark,typeof d.get,d.enumerable);", "7 8 true 9 undefined\n10 function false\n"];
        yield return ["inherited-accessor", "const O:any=Object,F:any=Function.prototype,k=Symbol('k');let seen=0;Object.defineProperty(F,k,{get:function(this:any){return this===O?seen:11;},set:function(this:any,value:any){console.log(this===O,value);seen=value;},configurable:true});O[k]=3;console.log(O[k],Object.hasOwn(O,k),k in O,Reflect.get(O,k,{}));", "true 3\n3 false true 11\n"];
        yield return ["inherited-readonly", "const O:any=Object,F:any=Function.prototype,k=Symbol('k');Object.defineProperty(F,k,{value:7,writable:false,configurable:true});O[k]=9;console.log(O[k],Object.hasOwn(O,k),Reflect.set(O,k,8));function strict(){'use strict';O[k]=10;}try{strict();}catch(error){console.log(error instanceof TypeError);}console.log(O[k],Object.hasOwn(O,k));", "7 false false\ntrue\n7 false\n"];
        yield return ["alternate-receiver", "const O:any=Object,k=Symbol('k'),receiver:any={};O[k]=1;console.log(Reflect.set(O,k,2,receiver),O[k],receiver[k],Object.hasOwn(receiver,k),Reflect.set(O,k,3,undefined));const d:any=Object.getOwnPropertyDescriptor(receiver,k);console.log(d.writable,d.enumerable,d.configurable);", "true 1 2 true false\ntrue true true\n"];
        yield return ["delete", "const O:any=Object,k=Symbol('k');O[k]=7;console.log(delete O[k],typeof O[k],Reflect.deleteProperty(O,k));Object.defineProperty(O,k,{value:8,configurable:false});console.log(delete O[k],Reflect.deleteProperty(O,k));function strict(){'use strict';delete O[k];}try{strict();}catch(error){console.log(error instanceof TypeError);}console.log(O[k]);", "true undefined true\nfalse false\ntrue\n8\n"];
        yield return ["prevent-extensions", "const O:any=Object,k=Symbol('k');Object.preventExtensions(O);console.log(Reflect.set(O,k,1),Object.hasOwn(O,k),Object.isExtensible(O));O[k]=2;console.log(typeof O[k]);try{Object.defineProperty(O,k,{value:3});}catch(error){console.log(error instanceof TypeError);}function strict(){'use strict';O[k]=4;}try{strict();}catch(error){console.log(error instanceof TypeError);}", "false false false\nundefined\ntrue\ntrue\n"];
        yield return ["freeze", "const O:any=Object,k=Symbol('k');O[k]=1;Object.freeze(O);const d:any=Object.getOwnPropertyDescriptor(O,k);console.log(Reflect.set(O,k,2),O[k],Reflect.deleteProperty(O,k),d.writable,d.configurable,Object.isFrozen(O));", "false 1 false false false true\n"];
        yield return ["seal", "const O:any=Object,k=Symbol('k');O[k]=1;Object.seal(O);const d:any=Object.getOwnPropertyDescriptor(O,k);console.log(Reflect.set(O,k,2),O[k],Reflect.deleteProperty(O,k),d.writable,d.configurable,Object.isSealed(O));", "true 2 false true false true\n"];
        yield return ["keys-and-descriptors", "const O:any=Object,a=Symbol('a'),b=Symbol('b'),c=Symbol('c');O.s=1;O[a]=2;Object.defineProperty(O,b,{value:3,enumerable:false});O[c]=4;const keys=Reflect.ownKeys(O).filter(k=>typeof k==='symbol'),symbols=Object.getOwnPropertySymbols(O),all:any=Object.getOwnPropertyDescriptors(O);console.log(keys.length,keys[0]===a,keys[1]===b,keys[2]===c,symbols[0]===a,Object.keys(O).includes('s'),Object.keys(O).includes(String(a)));console.log(all[a].value,all[b].enumerable,all[c].value,Object.prototype.propertyIsEnumerable.call(O,a),Object.prototype.propertyIsEnumerable.call(O,b));", "3 true true true true true false\n2 false 4 true false\n"];
        yield return ["transparent-proxy", "const O:any=Object,k=Symbol('k'),p:any=new Proxy(O,{});p[k]=1;console.log(p[k],O[k],Reflect.getOwnPropertyDescriptor(p,k)!.value,Reflect.ownKeys(p).includes(k),Object.hasOwn(p,k));console.log(delete p[k],typeof O[k]);", "1 1 1 true true\ntrue undefined\n"];
        yield return ["proxy-invariants", "const O:any=Object,k=Symbol('k');Object.defineProperty(O,k,{value:1,writable:false,configurable:false});const handlers:any[]=[{get(target:any,key:any,receiver:any){return key===k?2:Reflect.get(target,key,receiver);}},{ownKeys(target:any){return Reflect.ownKeys(target).filter(key=>key!==k);}},{deleteProperty(){return true;}},{getOwnPropertyDescriptor(target:any,key:any){return key===k?undefined:Reflect.getOwnPropertyDescriptor(target,key);}}];for(let i=0;i<handlers.length;i++){const proxy:any=new Proxy(O,handlers[i]);try{if(i===0)console.log(proxy[k]);else if(i===1)Reflect.ownKeys(proxy);else if(i===2)Reflect.deleteProperty(proxy,k);else Reflect.getOwnPropertyDescriptor(proxy,k);console.log('returned');}catch(error){console.log(error instanceof TypeError);}}", "true\ntrue\ntrue\ntrue\n"];
        yield return ["updates", "const O:any=Object,k=Symbol('k');O[k]=1;console.log(O[k]++,++O[k],O[k]);O[k]+=2;O[k]&&=9;console.log(O[k],Object.getOwnPropertySymbols(O)[0]===k);", "1 3 3\n9 true\n"];
        yield return ["copy-symbols", "const O:any=Object,k=Symbol('k');O[k]=7;const assigned:any=Object.assign({},O),spread:any={...O};const {name:ignoredName,...rest}=O;console.log(assigned[k],spread[k],rest[k]);const other=Symbol('other');Object.assign(O,{[other]:8});console.log(O[other],Object.hasOwn(O,other));", "7 7 7\n8 true\n"];
        yield return ["copy-key-snapshot", "const O:any=Object,a=Symbol('a'),b=Symbol('b');Object.defineProperty(O,'first',{enumerable:true,get(){O[b]=9;return 1;}});O[a]=7;const spread:any={...O};delete O[b];const assigned:any=Object.assign({},O);delete O[b];const {name:ignoredName,...rest}=O;console.log(spread[a],Object.hasOwn(spread,b),assigned[a],Object.hasOwn(assigned,b),rest[a],Object.hasOwn(rest,b),O[b]);", "7 false 7 false 7 false 9\n"];
        yield return ["define-properties-carrier", "const O:any=Object,a=Symbol('a'),b=Symbol('b'),events:string[]=[];Object.defineProperty(O,'added',{enumerable:true,get(){events.push('get');O[b]={value:8};return {value:1,enumerable:true};}});O[a]={value:7,enumerable:true};const out:any=Object.defineProperties({},O);console.log(out.added,out[a],Object.hasOwn(out,b),events.join(','),Object.hasOwn(O,b));", "1 7 false get true\n"];
    }
    public static IEnumerable<object[]> Modes() => Cases().SelectMany(row => new[] { ExecutionMode.Interpreted, ExecutionMode.Compiled }.Select(mode => new object[] { row[0],row[1],row[2],mode }));
    [Theory,MemberData(nameof(Modes))]
    public void ObjectConstructorSymbolsShareOrdinaryDescriptorsAndKeys(string name,string source,string expected,ExecutionMode mode)
    {
        Assert.NotEmpty(name);
        if(mode==ExecutionMode.Interpreted)Assert.Equal(expected,TestHarness.RunInterpreted(source));
        else {var(errors,output)=TestHarness.CompileVerifyAndRun(source);Assert.Empty(errors);Assert.Equal(expected,output);}
    }
    [Fact]
    public void SymbolStorageBelongsToTheCurrentRealm()
    {
        Assert.Equal("7\n",TestHarness.RunInterpreted("const O:any=Object,k=Symbol.for('object-symbol-realm');O[k]=7;console.log(O[k]);"));
        Assert.Equal("undefined false\n",TestHarness.RunInterpreted("const O:any=Object,k=Symbol.for('object-symbol-realm');console.log(typeof O[k],Object.hasOwn(O,k));"));
    }
}
